package com.cropdoctor.app.util

import android.content.Context

/**
 * UI language: English + Marathi + Hindi. Same scope as the web app
 * (web/src/i18n.js): everything the app itself writes is translated, while
 * free text written BY the model (symptoms, cloud review note, questions)
 * stays in English because the prompts and clean-detection rules require it.
 *
 * Reasons generated by RulesEngine are stored in the language active at
 * analysis time; switching language re-renders the chrome but not old
 * stored cases.
 */
enum class AppLang(val id: String, val label: String) {
    EN("en", "English"),
    MR("mr", "मराठी"),
    HI("hi", "हिन्दी");

    companion object {
        fun fromId(id: String?): AppLang = entries.firstOrNull { it.id == id } ?: EN
    }
}

private const val PREFS = "crop_doctor_prefs"
private const val KEY_LANG = "lang"

fun loadLang(context: Context): AppLang {
    val id = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        .getString(KEY_LANG, null)
    return AppLang.fromId(id)
}

fun saveLang(context: Context, lang: AppLang) {
    context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        .edit().putString(KEY_LANG, lang.id).apply()
}

fun stringsFor(lang: AppLang): LangStrings = when (lang) {
    AppLang.MR -> MR_STRINGS
    AppLang.HI -> HI_STRINGS
    AppLang.EN -> EN_STRINGS
}

/** Display name for a crop chip value or the model's English guess. */
fun cropDisplayName(raw: String, lang: AppLang): String {
    val t = raw.trim()
    if (t.isEmpty()) return ""
    if (lang == AppLang.EN) return t.replaceFirstChar { it.uppercase() }
    val s = stringsFor(lang)
    val key = t.lowercase()
    s.crops[key]?.let { return it }
    for ((k, name) in EN_STRINGS.crops) {
        if (key == name.lowercase() || key.contains(name.lowercase())) return s.crops[k] ?: name
    }
    // Same synonyms the crop-confirm chips understand.
    if (key.contains("corn")) return s.crops["maize"] ?: t
    if (key.contains("rice")) return s.crops["paddy"] ?: t
    if (key.contains("mirchi")) return s.crops["chili"] ?: t
    return t
}

